export function groupBy<T>(xs: T[], key: (x: T) => string): Record<string, T[]> {
  const out: Record<string, T[]> = {};
  for (const x of xs) {
    const k = key(x);
    (out[k] ||= []).push(x);
  }
  return out;
}

